{
  "findings": [
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "HIGH",
      "explanation": "The security group rule allows RDP (port 3389) access from any IP address (0.0.0.0/0), exposing the instance to brute-force attacks and unauthorized remote access."
    },
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The security group rule lacks a description, which hinders auditability and makes it difficult to understand the purpose of the rule in the AWS console or via API."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/8\"] # TODO: Replace with specific corporate IP range or VPN CIDR\n  description       = \"Allow RDP access from internal network only\"\n}",
  "fix_summary": "Restricted the RDP ingress rule from 0.0.0.0/0 to a private CIDR block (10.0.0.0/8) to prevent public exposure, and added a mandatory description field for better auditability."
}
